insert into speaker (name, role, org, location, pronoun, bio, handle) values
  ('Venkat Subramaniam', 'Award-winning author & founder', 'Agile Developer, Inc.', 'Chicago, US', 'he/him', 'Venkat has trained and mentored thousands of developers across five continents and authored a shelf of books on the JVM, functional programming, and pragmatic agility. On stage he turns dense platform internals into something you can actually use on Monday morning.', '@venkat_s'),
  ('Maya Petrova', 'Principal Engineer', 'Sofia AI Labs', 'Sofia, BG', 'she/her', 'Maya builds the integration layers that sit between large models and production Java services. She cares about boring reliability — backpressure, idempotency, graceful degradation — and the records-and-virtual-threads toolkit that makes it readable.', '@maya.codes'),
  ('Nikolay Ivanov', 'Staff Platform Engineer', 'CloudForge', 'Plovdiv, BG', 'he/him', 'Nikolay has spent a decade keeping JVM workloads honest on Kubernetes. He speaks from the scars of midnight pages: probes that lie, memory limits that surprise, and the deploy habits that make services boring in the best way.', '@nikolay.k8s'),
  ('Elena Markova', 'Lead Backend Architect', 'Northwind Bank', 'Varna, BG', 'she/her', 'Elena designs APIs that have to survive a decade of regulation, reorgs, and rewrites. Her talks are a field guide to versioning, contracts, and the small decisions that decide whether a service ages gracefully or rots.', '@elena.api'),
  ('Victor Stoyanov', 'Performance Engineer', 'Helix Trading', 'London, UK', 'he/him', 'Victor lives in flame graphs. From low-latency trading paths he brings a profiler-first mindset: measure, don''t guess, and respect the allocation. Expect live JFR recordings and a few uncomfortable truths about your hot loop.', '@vstoyanov'),
  ('Iva Georgieva', 'Developer Advocate', 'Quarkus Community', 'Berlin, DE', 'she/her', 'Iva translates between the framework maintainers and the people shipping with them. She runs hands-on workshops where the goal is that everyone leaves with code that compiled — not just slides they screenshotted.', '@iva.dev'),
  ('Georgi Dimitrov', 'Security Engineer', 'Sentinel Security', 'Sofia, BG', 'he/him', 'Georgi breaks Java apps so the audience doesn''t have to learn the hard way. His sessions walk the supply chain end to end — dependencies, secrets, and the defaults that quietly betray you in production.', '@gdimitrov.sec'),
  ('Daniela Koleva', 'Data Engineering Lead', 'Streamline Analytics', 'Burgas, BG', 'she/her', 'Daniela moves billions of events a day through JVM stream processors and still sleeps at night. She''ll show the schema discipline and replay strategies that keep a pipeline trustworthy when the data inevitably misbehaves.', '@daniela.streams'),
  ('Stefan Petrov', 'Engineering Manager', 'Mosaic Software', 'Sofia, BG', 'he/him', 'Stefan leads teams that have to balance feature velocity with a codebase they want to keep. He talks candidly about technical debt, refactoring under pressure, and the human side of keeping Java systems maintainable.', '@stefan.builds');
