insert into session (id, day_id, start_time, end_time, title, room_id, track, level, kind, plenary, description, status, sort_order) values
  ('k1', 1, time '09:00', time '09:25', 'Opening Keynote: Java''s Next Decade', (select id from room where name = 'Hall A'), 'Plenary', 'All levels', 'keynote', true, 'A wide-angle look at where the platform is heading — language ergonomics, the runtime, and the habits that keep Java teams productive over the next decade.', 'done', 1),
  ('s1', 1, time '09:30', time '10:20', 'Java 25: Patterns for Useful AI Assistants', (select id from room where name = 'Hall A'), 'Track 1', 'Intermediate', 'lecture', false, 'A practical tour of modern Java features for building reliable assistant workflows, including records, virtual threads, structured concurrency, and safer integration boundaries.', 'live', 2),
  ('s2', 1, time '09:30', time '10:20', 'Cloud Native Java on Kubernetes', (select id from room where name = 'Hall B'), 'Track 2', 'Advanced', 'lecture', false, 'A pragmatic look at packaging, probes, memory limits, and deploy habits that make JVM services behave predictably in Kubernetes.', 'live', 3),
  ('b1', 1, time '10:20', time '10:40', 'Coffee Break', (select id from room where name = 'Atrium'), 'Plenary', '', 'break', true, 'Refuel and meet the sponsor booths in the Atrium.', 'upcoming', 4),
  ('s3', 1, time '10:40', time '11:30', 'Spring Boot APIs That Age Well', (select id from room where name = 'Hall A'), 'Track 1', 'Beginner', 'lecture', false, 'Endpoint shapes, versioning habits, and validation details that keep public and internal APIs understandable as products evolve.', 'upcoming', 5),
  ('s4', 1, time '10:40', time '11:30', 'Production Observability Without Dashboard Fatigue', (select id from room where name = 'Hall B'), 'Track 2', 'Advanced', 'lecture', false, 'Design logs, traces, and alerts that help teams act during real incidents instead of creating another wall of red charts.', 'upcoming', 6),
  ('s5', 1, time '11:45', time '12:25', 'Workshop: Fast Feedback Loops for JVM Teams', (select id from room where name = 'Hall A'), 'Track 1', 'Intermediate', 'workshop', false, 'A hands-on look at test slicing, build profiling, and local environments that keep Java teams moving without lowering quality.', 'upcoming', 7),
  ('s6', 1, time '11:45', time '12:25', 'Modular Architecture for Busy Java Teams', (select id from room where name = 'Hall B'), 'Track 2', 'Intermediate', 'lecture', false, 'How to introduce module boundaries, package rules, and team-owned APIs inside a mature Java codebase without pausing delivery.', 'upcoming', 8),
  ('l1', 1, time '12:25', time '13:20', 'Lunch', (select id from room where name = 'Atrium'), 'Plenary', '', 'break', true, 'Lunch boxes are served in the Atrium. Workshop rooms stay open on level 2.', 'upcoming', 9),
  ('s7', 1, time '13:20', time '14:10', 'Virtual Threads in Practice', (select id from room where name = 'Hall A'), 'Track 1', 'Intermediate', 'lecture', false, 'Where virtual threads shine, where they don''t, and how to migrate blocking code without surprising your thread pools.', 'upcoming', 10),
  ('s8', 1, time '13:20', time '14:10', 'Event-Driven Systems with Kafka and Java', (select id from room where name = 'Hall B'), 'Track 2', 'Advanced', 'lecture', false, 'Designing resilient event flows — partitioning, idempotency, and the consumer habits that keep streaming pipelines healthy.', 'upcoming', 11),
  ('s9', 1, time '14:20', time '15:10', 'Workshop: Testing Strategies That Scale', (select id from room where name = 'Hall A'), 'Track 1', 'Intermediate', 'workshop', false, 'Hands-on patterns for fast, trustworthy test suites — test pyramids, contract tests, and pragmatic mocking.', 'upcoming', 12),
  ('s10', 1, time '14:20', time '15:10', 'JVM Performance Tuning Myths', (select id from room where name = 'Hall B'), 'Track 2', 'Advanced', 'lecture', false, 'Separating the GC folklore from the measurements that actually move latency and throughput in production.', 'upcoming', 13),
  ('b2', 1, time '15:10', time '15:30', 'Coffee Break', (select id from room where name = 'Atrium'), 'Plenary', '', 'break', true, 'Afternoon coffee and sponsor booths in the Atrium.', 'upcoming', 14),
  ('s11', 1, time '15:30', time '16:20', 'Records, Sealed Types, and Pattern Matching', (select id from room where name = 'Hall A'), 'Track 1', 'Beginner', 'lecture', false, 'Modeling data with modern Java language features for clearer, safer, and more maintainable domain code.', 'upcoming', 15),
  ('s12', 1, time '15:30', time '16:20', 'Securing Java Microservices', (select id from room where name = 'Hall B'), 'Track 2', 'Intermediate', 'lecture', false, 'Practical auth, secrets handling, and dependency hygiene for service meshes built on the JVM.', 'upcoming', 16),
  ('s13', 1, time '16:30', time '17:20', 'Data Access with Spring Data and JPA', (select id from room where name = 'Hall A'), 'Track 1', 'Intermediate', 'lecture', false, 'Mapping habits, query tuning, and the N+1 traps that quietly slow down data-heavy Java applications.', 'upcoming', 17),
  ('s14', 1, time '16:30', time '17:20', 'Reactive Java: When and Why', (select id from room where name = 'Hall B'), 'Track 2', 'Advanced', 'lecture', false, 'A grounded look at reactive programming trade-offs and how it compares to virtual threads for concurrency.', 'upcoming', 18),
  ('b3', 1, time '17:20', time '17:40', 'Coffee Break', (select id from room where name = 'Atrium'), 'Plenary', '', 'break', true, 'Last break of the day — grab a drink before the closing sessions.', 'upcoming', 19),
  ('s15', 1, time '17:40', time '18:30', 'Building Developer Tools with Java', (select id from room where name = 'Hall A'), 'Track 1', 'Intermediate', 'lecture', false, 'Lessons from building CLIs, plugins, and code generators that developers actually enjoy using.', 'upcoming', 20),
  ('s16', 1, time '17:40', time '18:30', 'From Monolith to Modular Monolith', (select id from room where name = 'Hall B'), 'Track 2', 'Intermediate', 'lecture', false, 'A migration story — extracting boundaries and team ownership without a risky big-bang rewrite.', 'upcoming', 21),
  ('k2', 1, time '18:30', time '19:00', 'Closing Keynote: The Joy of Shipping Java', (select id from room where name = 'Hall A'), 'Plenary', 'All levels', 'keynote', true, 'A closing reflection on craft, community, and the everyday habits that make shipping Java a genuinely enjoyable practice.', 'upcoming', 22),
  ('d2-k1', 2, time '09:00', time '09:25', 'Keynote: Inside the Modern JVM', (select id from room where name = 'Hall A'), 'Plenary', 'All levels', 'keynote', true, 'A guided tour under the hood — how the JIT, garbage collectors, and recent runtime projects quietly shape the performance of every Java application you ship.', 'upcoming', 1),
  ('d2-s1', 2, time '09:30', time '10:20', 'Project Leyden: Faster Startup, Smaller Footprint', (select id from room where name = 'Hall A'), 'Track 1', 'Advanced', 'lecture', false, 'Where ahead-of-time work is heading in the JDK and what Leyden''s condensers mean for startup time, warmup, and the shape of future deployments.', 'upcoming', 2),
  ('d2-s2', 2, time '09:30', time '10:20', 'GraalVM Native Image in Production', (select id from room where name = 'Hall B'), 'Track 2', 'Intermediate', 'lecture', false, 'Reflection config, build-time initialization, and the operational trade-offs of shipping native binaries instead of fat JARs.', 'upcoming', 3),
  ('d2-b1', 2, time '10:20', time '10:40', 'Coffee Break', (select id from room where name = 'Atrium'), 'Plenary', '', 'break', true, 'Refuel and meet the sponsor booths in the Atrium.', 'upcoming', 4),
  ('d2-s3', 2, time '10:40', time '11:30', 'Structured Concurrency Beyond the Basics', (select id from room where name = 'Hall A'), 'Track 1', 'Intermediate', 'lecture', false, 'Cancellation, scoped values, and error propagation patterns that make concurrent Java read like sequential code without the foot-guns.', 'upcoming', 5),
  ('d2-s4', 2, time '10:40', time '11:30', 'Taming the G1 and ZGC Collectors', (select id from room where name = 'Hall B'), 'Track 2', 'Advanced', 'lecture', false, 'A practical comparison of modern collectors — pause goals, heap sizing, and the telemetry you need before touching a single GC flag.', 'upcoming', 6),
  ('d2-s5', 2, time '11:45', time '12:25', 'Workshop: Profiling with JFR and async-profiler', (select id from room where name = 'Hall A'), 'Track 1', 'Intermediate', 'workshop', false, 'Hands-on flame graphs — capture a JFR recording, read allocation and lock profiles, and turn the findings into a concrete fix.', 'upcoming', 7),
  ('d2-s6', 2, time '11:45', time '12:25', 'The Foreign Function & Memory API in Anger', (select id from room where name = 'Hall B'), 'Track 2', 'Advanced', 'lecture', false, 'Calling native libraries and managing off-heap memory safely with the Panama APIs, and when the complexity actually pays off.', 'upcoming', 8),
  ('d2-l1', 2, time '12:25', time '13:20', 'Lunch', (select id from room where name = 'Atrium'), 'Plenary', '', 'break', true, 'Lunch boxes are served in the Atrium. Workshop rooms stay open on level 2.', 'upcoming', 9),
  ('d2-s7', 2, time '13:20', time '14:10', 'Scaling Postgres Access from the JVM', (select id from room where name = 'Hall A'), 'Track 1', 'Intermediate', 'lecture', false, 'Connection pools, prepared-statement caches, and the access patterns that keep a busy Java service from overwhelming its database.', 'upcoming', 10),
  ('d2-s8', 2, time '13:20', time '14:10', 'Resilient gRPC Services in Java', (select id from room where name = 'Hall B'), 'Track 2', 'Intermediate', 'lecture', false, 'Deadlines, retries, and backoff for service-to-service calls — the resilience details that decide how a mesh behaves under load.', 'upcoming', 11),
  ('d2-s9', 2, time '14:20', time '15:10', 'Workshop: Building a Native CLI with GraalVM', (select id from room where name = 'Hall A'), 'Track 1', 'Intermediate', 'workshop', false, 'Build a fast-starting command-line tool from a Java codebase, compile it to a native binary, and ship it as a single executable.', 'upcoming', 12),
  ('d2-s10', 2, time '14:20', time '15:10', 'Caching Strategies That Don''t Bite Back', (select id from room where name = 'Hall B'), 'Track 2', 'Intermediate', 'lecture', false, 'Invalidation, stampede protection, and the cache-shape decisions that keep a speed optimization from becoming a correctness bug.', 'upcoming', 13),
  ('d2-b2', 2, time '15:10', time '15:30', 'Coffee Break', (select id from room where name = 'Atrium'), 'Plenary', '', 'break', true, 'Afternoon coffee and sponsor booths in the Atrium.', 'upcoming', 14),
  ('d2-s11', 2, time '15:30', time '16:20', 'Memory Leaks: A Field Investigation', (select id from room where name = 'Hall A'), 'Track 1', 'Advanced', 'lecture', false, 'A whodunnit through heap dumps and dominator trees — how to find what''s holding references it shouldn''t, on a live JVM.', 'upcoming', 15),
  ('d2-s12', 2, time '15:30', time '16:20', 'Schema Evolution for Event Streams', (select id from room where name = 'Hall B'), 'Track 2', 'Advanced', 'lecture', false, 'Compatibility rules, registries, and migration habits that let Kafka topics evolve without breaking every consumer downstream.', 'upcoming', 16),
  ('d2-s13', 2, time '16:30', time '17:20', 'Designing for Backpressure', (select id from room where name = 'Hall A'), 'Track 1', 'Advanced', 'lecture', false, 'What happens when producers outrun consumers, and the bounded queues, rate limits, and load-shedding that keep systems standing.', 'upcoming', 17),
  ('d2-s14', 2, time '16:30', time '17:20', 'Zero-Downtime Database Migrations', (select id from room where name = 'Hall B'), 'Track 2', 'Intermediate', 'lecture', false, 'Expand-and-contract schema changes, backfills, and dual writes that let you reshape tables without a maintenance window.', 'upcoming', 18),
  ('d2-b3', 2, time '17:20', time '17:40', 'Coffee Break', (select id from room where name = 'Atrium'), 'Plenary', '', 'break', true, 'Last break of the day — grab a drink before the closing sessions.', 'upcoming', 19),
  ('d2-s15', 2, time '17:40', time '18:30', 'GraalVM Polyglot: Mixing Java and Beyond', (select id from room where name = 'Hall A'), 'Track 1', 'Intermediate', 'lecture', false, 'Embedding scripting languages inside JVM applications with the polyglot APIs, and where the boundary costs show up.', 'upcoming', 20),
  ('d2-s16', 2, time '17:40', time '18:30', 'Observability for Native Images', (select id from room where name = 'Hall B'), 'Track 2', 'Advanced', 'lecture', false, 'Metrics, tracing, and heap insight when there''s no JVM agent to attach — instrumenting GraalVM binaries in production.', 'upcoming', 21),
  ('d2-k2', 2, time '18:30', time '19:00', 'Keynote: Performance Is a Feature', (select id from room where name = 'Hall A'), 'Plenary', 'All levels', 'keynote', true, 'A closing argument for treating latency and footprint as product features, with the measurement habits that keep performance from quietly eroding release after release.', 'upcoming', 22),
  ('d3-k1', 3, time '09:00', time '09:25', 'Keynote: The Architecture of Tomorrow''s Java', (select id from room where name = 'Hall A'), 'Plenary', 'All levels', 'keynote', true, 'How language features, AI tooling, and modular thinking are reshaping the way we structure Java systems — and the principles that stay constant underneath.', 'upcoming', 1),
  ('d3-s1', 3, time '09:30', time '10:20', 'Hexagonal Architecture, Pragmatically', (select id from room where name = 'Hall A'), 'Track 1', 'Intermediate', 'lecture', false, 'Ports, adapters, and where the dogma helps versus hurts — a grounded take on keeping business logic free of framework gravity.', 'upcoming', 2),
