  ('d3-s3', 3, time '10:40', time '11:30', 'Domain-Driven Design Without the Dogma', (select id from room where name = 'Hall A'), 'Track 1', 'Intermediate', 'lecture', false, 'Aggregates, bounded contexts, and ubiquitous language explained through code you''d actually merge, not a 600-page ceremony.', 'upcoming', 5),
  ('d3-s4', 3, time '10:40', time '11:30', 'Embedding AI Models in JVM Services', (select id from room where name = 'Hall B'), 'Track 2', 'Advanced', 'lecture', false, 'Running and serving models from Java — batching, timeouts, and the integration boundaries that keep an inference call from sinking a request.', 'upcoming', 6),
  ('d3-s5', 3, time '11:45', time '12:25', 'Workshop: Refactoring Legacy Java Safely', (select id from room where name = 'Hall A'), 'Track 1', 'Intermediate', 'workshop', false, 'Characterization tests, seams, and small safe steps — practice taming a gnarly class without a rewrite and without fear.', 'upcoming', 7),
  ('d3-s6', 3, time '11:45', time '12:25', 'Contract Testing Across Teams', (select id from room where name = 'Hall B'), 'Track 2', 'Intermediate', 'lecture', false, 'Consumer-driven contracts that let independent services evolve without a fragile wall of end-to-end tests holding everyone hostage.', 'upcoming', 8),
  ('d3-l1', 3, time '12:25', time '13:20', 'Lunch', (select id from room where name = 'Atrium'), 'Plenary', '', 'break', true, 'Lunch boxes are served in the Atrium. Workshop rooms stay open on level 2.', 'upcoming', 9),
  ('d3-s7', 3, time '13:20', time '14:10', 'Property-Based Testing in Java', (select id from room where name = 'Hall A'), 'Track 1', 'Intermediate', 'lecture', false, 'Let the framework invent the edge cases — generators, shrinking, and the invariants that catch bugs example tests never reach.', 'upcoming', 10),
  ('d3-s8', 3, time '13:20', time '14:10', 'Securing the Software Supply Chain', (select id from room where name = 'Hall B'), 'Track 2', 'Advanced', 'lecture', false, 'SBOMs, signed artifacts, and dependency provenance — closing the gaps attackers use between your build and your users.', 'upcoming', 11),
  ('d3-s9', 3, time '14:20', time '15:10', 'Workshop: Build Pipelines Developers Trust', (select id from room where name = 'Hall A'), 'Track 1', 'Intermediate', 'workshop', false, 'Hands-on CI design — caching, parallelism, and flaky-test triage that turn a slow red pipeline into one teams actually believe.', 'upcoming', 12),
  ('d3-s10', 3, time '14:20', time '15:10', 'Threat Modeling for Java Services', (select id from room where name = 'Hall B'), 'Track 2', 'Intermediate', 'lecture', false, 'A lightweight, repeatable way to find the attacks that matter before code review, mapped to concrete JVM-side mitigations.', 'upcoming', 13),
  ('d3-b2', 3, time '15:10', time '15:30', 'Coffee Break', (select id from room where name = 'Atrium'), 'Plenary', '', 'break', true, 'Afternoon coffee and sponsor booths in the Atrium.', 'upcoming', 14),
  ('d3-s11', 3, time '15:30', time '16:20', 'The Art of the Code Review', (select id from room where name = 'Hall A'), 'Track 1', 'Beginner', 'lecture', false, 'Reviews that teach instead of gatekeep — tone, scope, and the small habits that make a team''s pull requests something people enjoy.', 'upcoming', 15),
  ('d3-s12', 3, time '15:30', time '16:20', 'Feature Flags and Progressive Delivery', (select id from room where name = 'Hall B'), 'Track 2', 'Intermediate', 'lecture', false, 'Decoupling deploy from release — flag hygiene, gradual rollouts, and the cleanup discipline that stops flags from becoming debt.', 'upcoming', 16),
