  ('d3-s14', 3, time '16:30', time '17:20', 'Migrating to the Java Module System', (select id from room where name = 'Hall B'), 'Track 2', 'Advanced', 'lecture', false, 'A staged path onto JPMS in a real codebase — split packages, automatic modules, and the strong encapsulation payoff at the end.', 'upcoming', 18),
